use std::io::Write;
use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Params { width: u32, height: u32 }
@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= p.width || id.y >= p.height) { return; }
    let x = id.x;
    let y = id.y;
    let l = select(x - 1u, 0u, x == 0u);
    let r = min(x + 1u, p.width - 1u);
    let u = select(y - 1u, 0u, y == 0u);
    let d = min(y + 1u, p.height - 1u);
    let w = p.width;
    let s = 4u * src[y * w + x] + src[y * w + l] + src[y * w + r]
          + src[u * w + x] + src[d * w + x];
    dst[y * w + x] = s / 8u;
}
"#;

fn parse(path: &str) -> Result<(usize, usize, usize, Vec<u32>), String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?;
    let mut it = text.split_ascii_whitespace();
    let mut next = |what: &str| -> Result<u64, String> {
        it.next()
            .ok_or_else(|| format!("missing {what}"))?
            .parse::<u64>()
            .map_err(|e| format!("bad {what}: {e}"))
    };
    let w = next("width")? as usize;
    let h = next("height")? as usize;
    let steps = next("steps")? as usize;
    if w == 0 || h == 0 || w > 512 || h > 512 {
        return Err("grid size out of range".into());
    }
    let mut cells = Vec::with_capacity(w * h);
    for _ in 0..w * h {
        cells.push(next("cell")? as u32);
    }
    Ok((w, h, steps, cells))
}

fn run(path: &str) -> Result<(), String> {
    let (w, h, steps, cells) = parse(path)?;

    let instance = wgpu::Instance::default();
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .ok_or("no GPU adapter")?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default(), None))
        .map_err(|e| e.to_string())?;

    let size = (w * h * 4) as u64;
    let params = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck_u32(&[w as u32, h as u32]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let usage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let buf_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck_u32(&cells),
        usage,
    });
    let buf_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: None,
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let make_group = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: params.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: src.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: dst.as_entire_binding() },
            ],
        })
    };
    let groups = [make_group(&buf_a, &buf_b), make_group(&buf_b, &buf_a)];

    let mut enc = device.create_command_encoder(&Default::default());
    {
        let mut pass = enc.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipeline);
        for s in 0..steps {
            pass.set_bind_group(0, &groups[s % 2], &[]);
            pass.dispatch_workgroups(w.div_ceil(8) as u32, h.div_ceil(8) as u32, 1);
        }
    }
    let result = if steps % 2 == 0 { &buf_a } else { &buf_b };
    enc.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit([enc.finish()]);

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device.poll(wgpu::Maintain::Wait);
    rx.recv().map_err(|e| e.to_string())?.map_err(|e| e.to_string())?;
    let data = slice.get_mapped_range();
    let out: Vec<u32> = data
        .chunks_exact(4)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    drop(data);

    let mut text = String::new();
    let mut sum: u64 = 0;
    for row in out.chunks(w) {
        let line: Vec<String> = row.iter().map(|v| v.to_string()).collect();
        sum += row.iter().map(|&v| u64::from(v)).sum::<u64>();
        text.push_str(&line.join(" "));
        text.push('\n');
    }
    text.push_str(&format!("SUM {sum}\n"));
    std::io::stdout()
        .write_all(text.as_bytes())
        .map_err(|e| e.to_string())
}

fn bytemuck_u32(v: &[u32]) -> &[u8] {
    // SAFETY: u32 has no padding and u8 has alignment 1.
    unsafe { std::slice::from_raw_parts(v.as_ptr().cast::<u8>(), std::mem::size_of_val(v)) }
}

fn main() {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu-heat <input-file>");
        std::process::exit(2);
    };
    if let Err(e) = run(&path) {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}
